"""Small read-only local progress page, also retained as a final results index."""
import argparse
from pathlib import Path

HTML='''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>扑翼悬停比较</title>
<style>body{background:#eff4f7;color:#243b4d;font:16px system-ui;margin:0}header{background:#153d50;color:#fff;padding:28px max(25px,calc((100vw - 1150px)/2))}main{max-width:1150px;margin:auto;padding:24px}.card{background:#fff;border:1px solid #d8e3e9;border-radius:12px;padding:20px;margin:18px 0}h1{font-size:28px;margin:0 0 12px}h2{font-size:20px}a{color:#08729a}progress{width:100%;height:22px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.metric{background:#f2f7f9;padding:16px;border-radius:8px}.metric b{font-size:24px;display:block}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:10px 7px;border-bottom:1px solid #dae4e9;text-align:left}.scroll{overflow:auto}.muted{color:#536e7e}img{width:100%}p{line-height:1.65}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style>
<header><h1>扑翼悬停：NEAT、SNN 与 PPO</h1><div>7 g + 8 g · 同一 PID 内环 · 11维观测 · 3个有符号控制残差</div></header><main>
<div class="card"><h2 id="stage">读取进度…</h2><progress id="overall" max="35" value="0"></progress><p id="current"></p><div class="grid"><div class="metric"><b id="runs">—</b>已完成正式训练</div><div class="metric"><b id="steps">—</b>当前运行分配交互</div><div class="metric"><b id="validation">—</b>当前选中策略验证成功率</div></div><p class="muted" id="scope">验证用于选模。独立测试完成前，不判断哪种方法更优。</p></div>
<div class="card"><h2>实验记录</h2><p><a href="report.md">report.md</a> · <a href="research_proposal_approved.md">已审阅方案</a> · <a href="protocol.json">冻结协议</a> · <a href="protocol_revision.json">修订与中断成本</a></p><div class="scroll"><table><thead><tr><th>方法</th><th>种子</th><th>实际训练步</th><th>验证成功</th><th>验证倾角RMS</th><th>选中策略</th></tr></thead><tbody id="completed"></tbody></table></div></div>
<div class="card" id="results" hidden><h2>最终证据</h2><p><a href="report_final.md">report_final.md：研究结果与贡献</a> · <a href="analysis.json">全部统计</a> · <a href="evolution_index.html">全部演化浏览器</a> · <a href="flight/snn_neat_stress.html">SNN 脉冲与膜电位</a> · <a href="verification.json">完整性核查</a></p><p><a href="https://github.com/MingshanHe/FlapSim/tree/research/neat-snn-hover">GitHub research/neat-snn-hover 分支</a>（最终报告在全部检查通过后推送）</p><img src="" id="performance"><p><a href="videos/comparison_stress_ann_neat.mp4">PID / SNN / ANN 扰动视频</a> · <a href="videos/comparison_stress_rnn_ppo.mp4">PID / SNN / PPO 扰动视频</a> · <a href="videos/snn_wings_stress_10x.mp4">翅膀10倍慢动作</a></p></div>
<p class="muted">每30秒读取本地进度；页面不启动训练，也不改变控制器。当前目标是姿态与高度稳定，yaw与水平位置不闭环。</p></main>
<script>const el=id=>document.getElementById(id);let prior='';async function get(p){const r=await fetch(p,{cache:'no-store'});if(!r.ok)throw Error(p+':'+r.status);return r.json()}
async function update(){try{const p=await get('protocol.json'),c=await get('campaign_status.json'),f=await get('finish_status.json');el('overall').value=c.completed;el('runs').textContent=c.completed+'/35';el('stage').textContent=c.status==='training_complete'?'训练完成 · 后处理：'+f.stage:'正式训练进行中';el('current').textContent=c.current?c.current.split('/').at(-1):'全部35次训练已完成';if(c.current){const s=await get('training/'+c.current.split('/').at(-1)+'/status.json');el('steps').textContent=(s.allocated_steps||s.training_steps).toLocaleString()+' / '+s.budget.toLocaleString();el('validation').textContent=s.best_validation?(s.best_validation.success_rate*100).toFixed(1)+'%':'—'}if(prior!==c.completed){const jobs=p.seeds.flatMap(seed=>p.methods.map(method=>({seed,method}))).slice(0,c.completed);let html='';for(const j of jobs){const path='training/'+j.method+'_seed'+j.seed,r=await get(path+'/results.json');html+=`<tr><td>${j.method}</td><td>${j.seed}</td><td>${r.training_steps.toLocaleString()}</td><td>${(r.best_validation.success_rate*100).toFixed(1)}%</td><td>${r.best_validation.tilt_rms_deg.toFixed(2)}°</td><td><a href="${path}/best_policy.json">模型</a></td></tr>`}el('completed').innerHTML=html;prior=c.completed}if(f.status==='completed'){el('stage').textContent='训练、独立测试、报告与完整性检查已完成';el('scope').textContent='结论见完整report.md；请同时阅读消融、全部种子和失败边界。';el('results').hidden=false;if(!el('performance').getAttribute('src'))el('performance').src='figures/performance_complexity.png'}}catch(e){el('scope').textContent='暂时无法读取进度：'+e.message+'。离线查看请打开report.md，动态页需通过本地服务器访问。'}}update();setInterval(update,30000);</script></html>'''

def main():
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);a=p.parse_args();(a.root/'dashboard.html').write_text(HTML,encoding='utf8')
if __name__=='__main__':main()
